import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"漢上易傳卷七","description":"漢上易傳 - 漢上易傳卷七","frontmatter":{"title":"漢上易傳卷七","description":"漢上易傳 - 漢上易傳卷七"},"headers":[],"relativePath":"classics/hanshang/008.md","filePath":"classics/hanshang/008.md"}'),n={name:"classics/hanshang/008.md"};function r(c,p,_,i,o,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="漢上易傳卷七" tabindex="-1">漢上易傳卷七 <a class="header-anchor" href="#漢上易傳卷七" aria-label="Permalink to “漢上易傳卷七”">​</a></h1><p>翰林學士、左朝奉大夫知制誥兼侍讀、兼資善堂翊善、長林縣開國男食邑三佰戶。賜紫金魚袋。朱震集傅。 天尊地卑，乾坤定矣。卑高以陳，貴賤位矣。動靜有常，剛柔斷矣。方以類聚，物以群分，吉㓙生矣。在天成象，在地成形，變化見矣。是故剛柔相摩，八卦相蕩，鼓之以雷霆，潤之以風雨。日月運行，一寒一暑。乾道成男，坤道成女；乾知太始，坤作成物。乾以易知，坤以簡能；易則易知，簡則易從。易知則有親，易從則有功。有親則可久，有功則可大。可久則賢人之德、可大則賢人之業。易簡而天下之理得矣。天下之理得。而成位乎其中矣。乾坤貴賤兩者、聖人觀天地而畫卦。剛柔吉㓙變化三者、聖人觀萬物而生爻。變化者、爻有變動也。伏羲畫卦、乾上坤下，立天地之位。歸藏先坤後乾，首萬物之母。連山乾始於子，坤始於午，至於周易，尊乾卑坤，其體乃定。見於卦，則上體乾也，下體坤也。道雖屢遷，上下不易。君尊臣卑，父尊子卑，夫尊婦卑，謂之三綱。三綱不正，天地反覆。高者貴，卑者賤，則貴賤之位分矣。陽為貴，乾也。陰為賤，坤也。高者，乾之位也。卑者，坤之位也。上既曰尊矣。尊無二上，故易尊為高，又曰卑。高者貴以賤為本，易自下升上，元士大夫三公諸侯承之，然後君位乎五也。動而不屈者，剛也。靜而不變者，柔也。動靜有常，則乾剛坤柔，其德斷而無疑矣。策數以七九為陽，六八為陰。陽，剛也，陰，柔也。爻位以一三五為剛，二四上為柔。陽先陰後，故策七者二十八，策九者三十六。爻一陽二陰，三陽四陰，五陽六陰。君不剛則臣強，父不剛則子強，夫不剛則為妻所畜。尊卑之位，貴賤之分也。五方之物，各以其類聚，同氣也。五物之類，各以其群分，異情也。氣同則合，情異則離，而吉凶生矣。爻或得朋，或失類，或遠而相應，或近而不相得，或睽而通，或異而同，陰，陽之情也。在天成象者，陰陽也。在地成形者，剛柔也。天變則地化，變者，陰陽極而相變也。陰陽之氣變於上，剛柔之形化於下，故策二十八者其數七，策三十二者其數八，策三十六者其數九，策二十四者其數六。陰陽交錯，剛柔互分，天地變化之道，乾坤之交也。乾以剛摩柔，坤以柔摩剛，剛柔相摩，八卦推蕩，變化彰矣。說卦謂之中爻。先儒謂之互體。鼓之以雷霆者，震反艮也。潤之以風雨者，巽反兌風而曰潤者。以雨而風，不以陰先陽也。日月運行，一寒一暑者，坎離也。六子致用，萬物化生。然不越乎乾坤也。震坎、艮之為三男，得乾之道也。巽、離兌之為三女，得坤之道者也。聖人之用天下，合乾坤也。父子君臣。乾坤也。夫婦。震巽坎離艮兌也。長幼其序也。朋同類也。友異體也。五者乾坤而巳矣。始於乾，終於坤。以乾知太始。坤作成物也。物生始於子，物成始於午。乾西北方亥也。陽藏於坤，有一而未形，知太始也。坤西南方，申也。物成於正秋，酉也。坤終於十月，亥也。坤作於申，成於酉，終於戌亥，作成萬物也。乾知大始，坤作成物，尊卑貴賤之分也。故父作子述，君佚臣勞，夫唱婦和。夫乾確然不易，無為而為萬物宗，以易知也。天動地隨，坤順乎乾，其作成萬物者，以簡能也。簡曰易從者，歸之乾也，與高不言尊，風雨言潤同義。聖人之於尊卑之際，君臣之大義嚴矣。孟子所謂一本，荀卿所謂一隆。易則其心一，故易知。簡則其政不煩，故易從。易知則天下見其憂樂，故有親。易從則匹夫匹婦各獲自盡，故有功。有親則不厭，故可久；有功則不巳，故可大。可久者，日新之德；可大者，富有之業。賢人者，賢於人者也。聖人，賢人之極。舜禹之聖，亦曰選賢與賢也。乾坤之理，盡於易簡，易簡而天下之理得。天下之理得，則上下與之同流，德業既成，乃位乎兩間，與天地為一。聖人設卦觀象，繫辭焉而明吉㓙。剛柔相推而生變化。是故吉㓙者，失得之象也。悔吝者，憂虞之象也。變化者，進退之象也。剛柔者，晝夜之象也。六爻之動，三極之道也。是故君子所居而安者。易之序也。所樂而玩者。爻之辭也。是故君子居則觀其象而玩其辭，動則觀其變而玩其佔，是以自天祐之，吉無不利。</p><p>聖人設卦，本以觀象，不言而見吉㓙。自伏犧至於堯、舜、文王，近者同時，遠者萬有千歲，其道如出乎一人，觀象而自得也。聖人憂患後世，懼觀之者，其智有不足以知此，於是系之卦辭，又系之爻辭，以明告之，非得巳也，為觀象而未知者設也。爻有剛柔，剛柔相推而生變化。變化微矣。非辭何以明之。象與辭反覆相發也。是故辭之有吉㓙者，人有得失之象也。辭之有悔吝者，人有憂虞之象也。失得者，剛柔相文有當否也。失者能憂虞之，俄且得矣。得者憂虞有不至焉，俄且失矣。悔其失者或致吉，吝其失者或致兇。變化也。變化之於剛柔，猶進退之於晝夜。變化者，進退之象。剛柔者，晝夜之象。晝推而進則夜退柔者變而剛。夜推而進則晝退剛者變而柔。晝夜之進退無止，剛柔之變化不窮，憂虞異情，得失殊致，故曰吉㓙悔吝生乎動。變化者，動爻也。六爻之動，三極之道也。一生二，二生三，三極矣。邵雍曰：易有真數三是也。關子明曰：天三，數之極也。極乎終則反乎始，兼兩之義也。故極而不變，其道乃窮。說卦震，其究為健，三變而乾也。巽，其究為躁，卦，三變而震也。觀此可以例餘卦矣。是故君子所居而安者，易貴賤之序也。所樂而玩者，文吉凶之辭也。居則觀其卦之象而玩其辭，動則觀其爻之變而玩其佔。易以變為佔，於佔言變，則居之所玩，末變之辭也。居處動作，無非道也，天人一理也。是故自天祐之，吉無不利。彖者，言乎象者也；爻者，言乎變者也。吉凶者，言乎其失得也；悔吝者，言乎其小疵也。無咎者，善捕過也。是故列貴賤者存乎位，齊小大者存乎卦，辯吉凶者存乎辭，憂悔吝者存乎介。震無咎者存乎悔。是故卦有小大，辭有險易。辭也者，各指其所之。</p><p>設卦觀象，默而識之。不得巳而有彖者，所以言乎一卦之象也。玩其彖辭而不得，觀其象可也。剛柔相推而生變化，吉凶有難知者，故有爻辭，所以言乎一爻之變也。玩其爻辭而不得觀其變可也。吉凶者，言如是而得則吉，如是而失則兇。悔吝者，言乎小疵也。惡積罪大，則悔無及。巳言者，言當悔而止，護小疵致大害者也。無咎者，本實有咎，善補過而至於無咎。易有言又誰咎者，言咎實自取，自咎可也。有言不可咎者，義所當為，才不足也。君子度德量力，折之以中道，則無咎矣。吉凶悔吝無咎，一也，其實悔吝無咎，所以明吉凶也。彖不言悔而言無咎，無咎則悔可知矣。言兇而不言吝，吝不足言也。卦自下而上，列貴賤之位存乎位，則剛柔往來，上下內外，得位失位，或應或否見矣。易於小事不忽，於大事不懼，視履尊位，與居家同，視征伐天下，與折獄同，視享上帝、養聖賢、養萬物，與飲食同。知此則知顏子與禹稷同，曾子與子思同，故存乎卦之小大，則見事之小大齊矣。憂悔吝之將至者，當存乎介。介者，確然自守，不與物交。震懼而無咎者，當存乎悔。悔者，追悔前失而不憚改也。故悔則無咎，介則無悔，不近於知幾乎？幾者，動之微，吉之先見也。易曰：介於石，不終日，貞吉。確然自守者，守正也。辭有易者之於吉也，所謂能說諸心；辭有險者之於兇也，所謂能研諸慮。有憂慮悔吝，非險辭不足以盡之。爻辭也，各指其所之之險易也。所之者，動爻也，言乎其變也，春秋傳觀其動，曰之某卦是也。從其所之，乃能趨時盡利，順性命之理，則繫辭焉以命之，不可巳也。</p><p>易與天地準，故能彌綸天地之道，仰以觀於天文，俯以察於地理，是故知幽明之故。原始反終，故知死生之說。精氣為物，遊魂為變，是故知鬼坤之情狀與天地相似，故不違。知周乎萬物而道濟天下，故不過；旁行而不流。樂天知命，故不憂；安土敦乎仁，故能愛。範圍天地之化而不過，曲成萬物而不遺，通乎晝夜之道而知，故神無方，易無體。一陰一陽之謂道，繼之者善也，成之者性也。仁者見之謂之仁，知者見之謂之知，百姓日用而不知，故君子之道鮮矣。</p><p>王昭素離易與天地準，合精氣為物，通為一章，今從昭素。聖人觀天地以作易，其道甚大，與天地均，故能用天地之道，彌滿無間，綸經而不絕。天，氣也，而鹹文；地，形也，而有理。形散為氣，明而幽也；氣聚成形，幽而明也。仰觀乎天，凡地之成形者，莫不有是文；俯察乎地，凡天之成象者，莫不具是理。故分而為二，揲之以四生、二儀、四象、八卦，成三百八十四爻，萬有一千五百二十策，皆源於太極。知此則知幽明之故也。聚而為有，生之始也；散而入無生之終也。始終循環，死生相續，聚散之理也。以八卦觀之，一變者，卦之始也，謂之一世；六變者，卦之終也，謂之遊魂。七變而反者，卦體復也，謂之歸魂。始者，生也。終者，死也。反則死而復生，故知此則知死生之說也。乾、兌，金也。震、巽，木也。坎，水離，火也。坤、艮，土也。乾、震、坎、艮，陽也。坤、巽、離、兌，陰也。陰，陽之精，五行之氣，</p><p>氣聚為精，精聚為物。得乾為首，得坤為腹，得震為足，得巽為股，得坎為耳，得離為目，得艮為𤾁，得兌為口。及其散也，五行陰陽，各還其本，故魂陽反於天，魄陰歸於地。其生也，氣日至而滋息；物生既盈，氣日反而遊散。至之謂神，以其申也；反之謂鬼，以其歸也。陰陽轉續，觸類成形，其遊魂為變乎，物，其狀也，聚散。其情也。故曰。乾。陽物也。坤，陰物也。知此則知鬼神之情狀矣。或曰。太史公言。儒者不言鬼神。而言有物。物與鬼神異乎。曰。人生始化曰魄。既生陽曰魂。至於死也。體魄降而魂氣升。升則無不之也。魄降而氣不化者。物也。今人行氣中。若哭若呼。其人忤視，俄且化矣。謂誠有是，而不知氣之不化者也。謂鬼為物，察之有不至也，韓愈謂鬼無聲形是也。生蓍、立卦、生爻三者，準天地也。自此以下，言彌綸天地之道。易與天地準，天地無一物不體，有違於物，則與天地不相似。與天地相似，故不違。此言易之時也。性者，萬物之一源，知性則知天，知天則知物，無非我者，故智周乎萬物。智周乎萬物，而不知以道濟天下，則過矣。唯知周萬物而道濟乎天下，故不過。此言易之體也。道濟天下，酬酢萬變，其道旁行散徙，流而不反，徇物而喪巳，亦過矣，故道濟天下，旁行而不流，此言易之用也。道之行否有命，窮亦樂，通亦樂，不以天下累其心，故不憂，此言易之貞也。安土者，所遇而安也。雖所遇而安，亦未嘗一日誌天下，篤於仁者也，故能愛。此言易正而亨也。範圍者，防範之所圍，天子所謂矩，莊周所謂大方。天地之化者，氣也。氣之推移，一息不留，故謂之化。善養其氣者，大配天地。不違也，不過也，不流也。雖憂樂以天下，而適乎大中至正之矩，故不過。不過者，不過乎中也。橫渠謂非也，絕物而獨化是也。此言易之中正也。不過故能盡巳之性，能盡巳之性，則能盡物之性。曲成者，順萬物之理，成之者非一方也。天之生物也直，聖人相天而曲成之，不害其為直，此言中正之成物也。曲成萬物而不遺，乃能無一物不體，與天地相似，與時偕行矣。晝夜者，陰陽也。推乎晝夜陰陽之道而通之，則知幽明，知死生，知鬼神，非盡巳之性，盡物之性者不能也。故通乎晝夜之道而知陰陽，兩也。兩者合一而不測者，神也。不測則無方。剛柔雜居而相易者，用也。相易則無體。知易無方，則知易無體，知易無體，則知一陰一陽之道。一陰一陽在天，日月之行也，晝夜之經也，寒暑之運也，在人，屈伸也，動靜也，語默也，推而行之，故以是名之為道。知一陰一陽之道，則繼之而不巳者善也。君子晝有為，宵有得，息有養，瞬有存，亹亹焉，孜孜焉，不敢湏臾舍也。夫性無有不善，不善非天地之性，剛柔之氣，或得之偏，乃有不善，有不善然後善之名立，善不善相形而後命之也。善反其初者，不善盡去，則善名亦亡，故舍曰善而成之者性也。性自成也，豈人為哉。性即天地也，所謂誠也。仁者見其道濟天下，得易之體也，故謂之仁。智者見其旁行而不流，得易之用也，故謂之知。百姓習焉而不察，行之而不著，故曰用而不知。君子之道，仁智合體，用一兼體，陰陽而無累，通乎晝夜之道而知，故君子之道鮮矣。君子者，具仁智之成名，得道之大全者也。</p><p>顯諸仁，藏諸用，鼓萬物，而不與聖人同憂，盛德大業至矣哉！富有之謂大業，日新之謂盛德，生生之謂易，成象之謂乾，效法之謂坤，極數知來之謂佔，通變之謂事，陰陽不測之謂神。夫易廣矣大矣，以言乎遠則不御，以言乎邇則靜而正，以言乎天地之間則備矣。夫乾，其靜也專，其動也直，是以大生焉。夫坤，其靜也翕，其動也闢，是以廣生焉。廣大配天地，變通配四時，陰陽之義配日月，易簡之善配至德。子曰：易其至矣乎！夫易，聖人所以崇德而廣業也。知崇禮卑，崇效天，卑法地，天地設位，而易行乎其中矣。成性存存，道義之門，</p><p>天道之行，雷霆風雨，日月寒暑，剛柔相摩，萬物變化，顯諸仁也。雷霆之所以鼓，風雨之所以潤，日月寒暑之所以運行，莫知其然而然，藏諸用也。天理自動，萬物聽之，鼓萬物也。此天道無心之妙，猶不與聖人同憂者，蓋聖人有相之道，不以其所可憂者而同乎無憂，以謂配天地立人道者存乎巳，易之道是巳，則聖人盛德大業，豈不至矣乎。橫渠曰：富有者，大而無外也。日新者，久而無窮也。陽生陰，陰生陽，陽復生陰，陰復生陽，生生不窮，如環無端，此之謂易。太極不動，則含兩儀，動而生陽，一太極兩儀而成象，此天所以三也。靜而生陰，陰配於陽，猶形之有影，故兩剛柔男女而效之法，此地所以兩也。成象者，健也，此之謂乾。效法者，順也，此之謂坤。天數二十有五，地數三十，極天地之數，而吉凶之變可以前知，此之謂佔。窮則變，變則有術以通之，此之謂事。陰陽變化，不可測度，此之謂神。是道也，在聖人為德業，在天地之用為易，在易為乾坤，為佔、為神。以兩言該之曰仁智，以一言該之曰道，其實一也。廣者，坤也；大者，乾也。以言乎遠者，變動也，入於無形，莫之能御也；以言乎邇者，不變者也，靜而守正，一天下之動者也。以言乎天地之間，則乾坤合德，剛柔有體，變與不變，玄相推蕩，而萬物備矣，廣矣，大矣，備矣，所謂富有也。夫乾之靜，以一陽藏於二陰之中，陰不能橈，故專。其動也。九變為六，依坤而行，故直。坤之靜也，以一陰藏於二陽之中，隨陽而入，故翕。及其動也，六變而九，從乾而出，故闢。直則自遂，闢則浸昌。大生者通乎形外，廣生者用止乎形。此廣大之辯也。天地之大德曰生，乾坤不相離也，是以能廣大，故廣大配天地。變通者，乾坤之動也，故變通配四時。乾坤之動者，陰陽之變也，故陰陽之義配日月，日月相推而明生焉，故也。言乎天地之間者備矣。其究則乾坤簡易而巳。至德者，天地之德隱於無形者也，故簡易之善配至德。夫子於太伯之讓，文王之德，孝也，中庸也，皆謂之至德。德至於是，無以復加矣，將以崇德，故知崇；將以廣業，故禮卑。崇上達易，自下升也。卑無不至，易徧體也。通乎晝夜之道而知，可謂知崇矣。知崇則德崇，曲成萬物而不遺，可謂禮卑矣。禮卑則業廣，知崇效天，禮卑法地，德崇業廣，則上下與天地同流。易者，天地之用也。尊卑有定，天地設位，六爻上下升降，而易行乎其中矣。成性者存其所存，則天地位，天地位則道義出。道義者，用也。故曰一陰一陽之謂道。又曰道有變動，又曰精義入神以致用。夫萬物皆備於我，而存其所存者，何也？去人慾而天理存也。</p><p>聖人有以見天下之賾，而擬諸其形容，象其物宜，是故謂之象。</p><p>聖人有以見天下之動，而觀其會通，以行其典禮，繫辭焉以斷其吉凶，是故謂之爻。言天下之至賾而不可惡也，言天下之至動而不可亂也。擬之而後言，議之而後動，擬議以成其變化。鳴鶴在陰，其子和之，我有好爵，吾與爾靡之。子曰：君子居其室，出其言善，則千里之外應之，況其邇者乎？居其室，出其言不善，則千里之外違之，況其邇者乎？言出乎身，加乎民；行發乎邇，見乎遠。言行，君子之樞機。樞機之發，榮辱之主也。言行，君子之所以動天地也。可不慎乎！同人。先號啕而後笑。子曰：君子之道，或出或處，或默或語。二人同心，其利斷金；同心之言，其臭如蘭。</p><p>初六，藉用白茅，無咎。子曰：苟錯諸地而可矣，藉之用茅，何咎之有？慎之至也。夫茅之為物薄，而用可重也。慎斯術也，以往其無所失矣。勞謙君子有終，吉。子曰：勞而不伐，有功而不德，厚之至也。語以其功，下人者也。德言盛，禮言恭。謙也者，致恭以存其位者也。亢龍有悔。子曰：貴而無位，高而無民，賢人在下位而無輔，是以動而有悔也。不出戶庭，無咎。子曰：亂之所生也，則言語以為階。君不密則失臣；臣不密則失身；幾事不密則害成。是以君子慎密而不出也。子曰：作易者，其知盜乎？易曰：負且乘，致寇至。負也者，小人之事也；乘也者，君子之器也。小人而乘君子之器，盜思奪之矣。上慢下暴，盜思伐之矣。慢藏誨盜，冶容誨淫。易曰：負且乘，致寇至，盜之招也。</p><p>王昭素合初六藉用白茅，通為一章，今從昭素。天下之至頤者，理也；天下之至動者，時也。畫卦以明理，而卦有變；生爻以明時，而爻有動。擬諸其形容者，剛柔有體；象其物宜者，百物不廢，是故謂之象會。通者，亨也。典禮者，大猷也。觀時之會否者，既通則斟酌大猷，損益而行之，所以嘉其亨之會也。又繫辭以斷其吉凶，知用各有時，時不可失，是故謂之爻。如顛趾出否，豕塗鬼車，言天下之至頤也。然象其物之所宜，雖至頤而不可惡也。如升降上下，反覆相變，言天下之至動也。然斷之以吉凶，雖至動而不可亂也。言者尚其辭，故擬之而後言，則無妄言。動而尚其變，故議之而後動，則無妄動。擬議以成其變化，則語默動靜皆中於道。易言變化者四：曰天地變化者，乾坤變化也。曰乾道變化者，乾之變化也。曰剛柔相推而生變化者，爻象之變化也。曰擬議以成其變化者，言行之變化也。或語或默，或出或處，變化也。爻象之變化象天地，故曰天地變化，聖人傚之。言行之變化體易也。自此以下，舉諸卦以明擬議，以明成其變化者如是。靡當作縻。中孚九二辭也。二在內，居室也。二動五應，出其言善，千里之外應之也。兌口不動則不正。巽五不應，出其言不善，千里之外違之也。坤為眾，行出乎身，加乎民也。內近外遠，言發乎邇，見乎遠也。艮門震動，樞機也。或應或否，榮辱之主也。乾坤天地，震巽相應，動天地也。明擬之而後言，議之而後動者，當如是。此動彼應，非變化乎？同人先號啕而後笑，同人，九五辭也。五應二也。乾變為金，兌金斷之，故曰其利斷金。言同心之利，動而不括者然也。巽為草，為臭，陽為芬芳，二五相易，芬芳上達，兌為口，故曰同心之言。其臭如蘭。言可服也。震動。或語或出也。艮止。或處或默也。出處語默不必同所同者心。則其利可斷。其言可服。變化不同。其歸同也。明言行不必同也。中孚同人。二五相易。乃成變化。故曰一則神。兩則化。一者。合兩而為一也。爻辭曰。用大師。克相遇五，四動而克三，乃與二遇。繫辭所陳，止以二五相易，盡同心之義，是謂玩辭玩變之道，舉上二爻以例爻之變者也。藉用白茅，無咎。大過初六爻辭也。初六一柔承四剛，執柔處下而不犯，雖柔無咎。譬之置器，苟錯之於平安之地，斯可矣。又藉之以潔白之茅，慎之至也。茅之為物雖薄，而祭祀用之可謂重矣。持是以往，何以尚之？明言行之當慎也。勞謙君子有終吉者，謙九三爻辭也。坎為勞，九三體謙，以陽下陰，勞而不自伐，有功而不自得，厚之至也。語以其功下人者也。艮成始成終，成功之象，明言行之當謙也。德者，言盛者也，厚之至是也。禮者，言恭者也。禮自卑而尊人，自後而先人，故以恭言之。君子之於謙也，豈唯下人，亦所以存其位。存其位，非固位有終吉也。謙恭則其德厚矣。亢龍有悔，乾上九爻辭也。不當尊位，無位也。乾見坤隱，坤為眾，無民也。九三不應，無輔也。上乃剛過亢滿，不知謙降之道，是以動而有悔，違謙故也。不出戶庭，無咎，節初九爻辭也。兌為口，動於內為舌。初應四，出戶庭也。是為否亂之階。初四易，則乾君受言，坤臣納言。離為明，坎為難，明言而有難，不密之害也。初四尖位。君臣失也。初乾為君。四坤為臣。初為事。幾成於四。四失而難作。害成也。不出戶庭。坎離象隱。是以君子慎密而不出言。此以明不慎不密之戒。易曰：負且乘，致寇至。解九三辭也。以小人而乘君子之器。則為盜者不奪。不厭。故思奪之。四坎為盜，三四同象。六三據非其位，上慢也。以柔乘剛，下暴也。上下惡之，盜將聲其罪，故思伐之。離為戈兵，三四易位，自上伐下也。慢藏者誨人使盜，冶容者誨人使淫，無不自已求之負。且乘致寇至，盜之招也。故子曰：作易者其知盜乎！言此以明致恭可以存位，慢則盜奪之，伐之為不恭之戒，舉上五爻以例爻之不變者也。夫謙恭慎密，又知夫不密不恭之戒，則於言行也何有？善易者也。易豈止於文字而巳哉！</p><p>大衍之數五十，其用四十有九，分而為二以象兩，掛一以象三，揲之以四，以象四時，歸奇於扐以象閏。五歲再閏，故再扐而後掛。天數五，地數五，五位相得而各有合。天數二十有五，地數三十，凡天地之數五十有五，此所以成變化而行鬼神也。乾之策二百一十有六，坤之策百四十有四，凡三百有六十，當期之日。</p><p>二篇之策萬有一千五百二十，當萬物之數也。是故四營而成易，十有八變而成卦，八卦而小成。引而伸之，觸類而長之，天下之能事畢矣。顯道神德行，是故可與酬酢，可與祐神矣。小衍之五，參兩也。大衍之五十，則小衍在其中矣。一者，體也，太極不動之數。四十有九者，用也。兩儀四象分太極之數，總之則一，散之則四十有九。非四十有九之外復有一，而其一不用也。方其一也，兩儀四象未始不具；及其散也，太極未始或亡，體用不相離也。四十有九者，七也。是故爻用六，蓍用七，卦用八，玄用九。十即五也。十盈數，不可衍也。分之左右而為二以象兩者，分陰陽剛柔也。掛一於小指以象三者，一，太極兩儀也。揲之四以象四時者，陰陽寒暑即四象也。歸奇於扐以象閏者，先以其左四揲之，歸其所揲之餘而扐之以象閏；次以其右四揲之，歸其所揲之餘而扐之，以象五歲再閏。故再扐而後復掛，皆參兩也。三揲而成一爻。閏生於日月合朔周天不盡之氣，十九歲七閏。凡三歲閏者五，二歲閏者二，太率五歲再閏，所以定四時成歲也。韓康伯曰：其間五歲再閏者二，故舉其凡。是以太一筭數。關子明卜百年之義。皆源於此。京房以五十為</p><p>十日。十二辰二十八宿。馬融謂北辰日月五行十二月二十四氣。誤也。或謂每成一爻。而後掛二揲。三揲不掛。亦誤也。一三五七九。奇也。故天數五。二四六八十。偶也。故地數十。九者。河圖數也。十者，洛書數也。五位相得者，一五為六，故一與六相得。二五為七，故二與七相得。三五為八，故三與八相得。四五為九，故四與九相得。五五為十，故五與十相得。然各有合，故一與二合，丁壬也；三與五合，甲巳也。五與六合，戊癸也。七與四合，丙辛也。九與八合，乙庚也。五即十也。天地五十有五，大槩如此，故曰凡天地之數五十有五。然五十則在其中，故太玄一六為水，二七為火，三八為木，四九為金，五五為土。黃帝書亦曰：土生數五，成數五。是以大衍之數五十也。大衍之數五十，而策數六七八九，何也？曰：六者，一五也；七者，二五也。八者，三五也；九者，四五也。舉六七八九，則一二三四五具。所謂五與十者，未始離也。五與十，中也，中不可離也。考之於歷，四時迭王，而土王四季，凡七十有五日，與金木水火等。此河圖十五，隱於一九三七二四六八之意。劉牧曰：天五居中，主乎變化，三才既備，退藏於密是也。故六七八九而五十之數具，五十之數，而天地五十有五之數具。奇耦相合也，故能成變化。相合而有升降也，故能行鬼神。變化鬼神者，天地也。成之行之者，人也。太玄：天之策十有八，地之策十有八，虛其三以扐之，準大衍之數，其用四十有九也。雖虛其三，而三畫成首，首有三表，七八九為用，亦大衍五十而五在其中也。凡此言天地之數五十有五，而大衍之數，其用四十有九者為是也。自此以下，再論揲之四以象四時，歸奇合耦之數，得五與四四，則策數三十六。四九也，是為乾之策。乾之策，老陽也，得九與八八，則策數二十四。四六也，是為坤之策。坤之策，老陰也，得五與八八，得九與四八，策數皆二十八，四七也，是為震坎。艮之策，少陽也，得九與四四，得五與四八，策數皆三十二，四八也，是為巽、離。兌之策，少陰也，三十六合二十四，六十也。二十八合三十二，亦六十也。乾之策六爻二百一十有六。坤之策六爻一百四十有四。</p><p>乾、坤之策凡三百有六十，當期之日，具四時也。震、坎、艮之策六爻一百六十有八。巽、離、兌之策，六爻一百九十有二。震、坎、艮、巽、離、兌之策，凡三百有六十。亦當期之日，舉乾、坤，則六卦舉矣。老者變，少者不變，易以變為佔者也。變則化成，變化則鬼神行矣。管子曰：流行於天地之間，謂之鬼神。歸奇合耦之數，所以異於策數者，存其掛一之數也。一者，太極不動之數。故五與四四合為十三，去其一則十二。九與八八合為二十五，去其一則二十四。五與八八合為二十一。九與四八合亦二十一，去其一則皆二十。九與四四合為十七，五與四八合亦十七，去其一皆十六。一體也，體隱則用顯，所謂顯者亦隱。故二十四者，老陰之策也。以二十四合十二，則三十六者，老陽之策也。以二十合十二，則三十二者，少陽之</p><p>策也。以十六合十二，則二十八者，少陰之策也。二十四合三十六，六十也。二十八合三十二，亦六十也。用與不用通而為一體，無非用也。劉牧謂經唯舉乾、坤、老陽、老陰三百六十之數，當期之日，不更別舉他卦之爻，而疑六日七分之義，此不以三隅反也。唐陸希聲謂，易以年統月，以歲統旬，以日統時，凡言月者，以一策當一月，一九之策三十有六，是為三年。故曰皆一九之策也。又曰：以年統月，一日十二時，七日八十四時，一九之策三十六，二六之策四十八，凡八十有四，是為七日八十四時。故曰七日者，一九二六之策也。又曰：以日統時，一朔之旬三十日七，二十八策八三十二策，凡六十策，半之為三十，故曰：言旬者，合七八之策而半之，以象一朔之旬。一閏三十日，再閏六十日，九三十六策，六二十四策，凡六十策。故曰：言歲者全之，以象再閏之日。月有朔虛，故半之，歲有中盈，故全之。一月三旬，八月二十四旬，而老陰之策二十有四，故曰八月之旬當極。陰之策二十有四，三歲為一閏，一歲三百六十日，而二篇之爻三百八十有四，除三百六十日餘二十四日，故曰閏之日當二篇之爻八十有四，乾坤之策當期之日而少六日，故曰虛分包焉。二篇之爻三百八十四，爻多二十四日，故曰盈分萃焉。其說本於繫辭坤乾之策，當期之日，然時有牴牾。且虞翻為孫權筮關羽，遇節五爻變之臨，曰：不出二日。五應二，以二爻為日也。尚廣為孫皓筮並天下，遇同人之頤曰：庚子歲。青蓋入洛。庚子，震初爻也。震少陽，數七。鳳凰元年至天紀四年春三月，吳入晉，實七年。若以一九二六之策推之，為八十四時，則可以言七日，不可言七歲七年矣。又臨至於八月有兇者，謂自複數至遁一爻為一月，非取二十四極陰之策。若二爻屬老陰，四十八策，不可言十六月矣。不然，當言一歲四月乎？中條隱者謂易含萬象，策數乃數之一，又有爻數、卦數、五行、十日、十二辰、五聲、十二律，納甲之數，不可一端而盡。二篇之策，三百八十四爻，陽爻一百九十二，其策六千九百一十二，陰爻一百九十二，其策四千六百八。二篇之策，合之凡萬有一千五百二十，當萬物之數。此變爻也。老陽，老陰之策也。以不變者論之。少陽之策二十有八。凡一百九十二爻，為五千三百七十六策。少陰之策三十有二。凡一百九十二爻，為六千一百四十四策。二篇之策合之亦萬有二千五百二十。當期之日，變者以不變為基，不變者以變者為用。以爻數言之，陽爻一百九十二，晝數也，其數一千七百二十八；陰爻一百九十二，夜數也，其數一千一百五十二。綜而言之，二十八百八十。凡四求之，亦萬有一千五百二十，當萬物之數。四時行而後萬物生，無非四也，故曰四營而成易。分二掛一，歸四揲之餘，而並扐之一變也。三變而成一爻，六爻十有八變而成卦，自乾至坤，八卦而小成，引而伸之，為六十四卦，觸類而長之，乃有變動。或謂三畫之卦為小成，誤也。上既陳十有八變而成卦，則八卦者重卦也。八卦而六十四卦具，故曰小成。自歸奇合扐之數觀之，三少者，乾也；三多者，坤也；一少二多者，震、坎、艮也；二少一多者，巽、離、兌也。三少者策數九，三多者策數六；一少二多者策數七，一多二少者策數八，則多少之數，八卦已具。自三畫觀之，八卦為陽畫者十有二，陰畫者二十有四。陽七九也，陰六八也，九六十五也，七八亦十五也。二十四者，坤策也，總而為三十六者，乾策也。則三畫之中，五行十日、十二辰、二十四氣巳具，引而伸之，觸類而長之，不越乎此。是故聖人語小，天下莫能破，語大天下莫能載。謂八卦而小成者，舉中而言也。顯道者，危者使平，易者使傾，懼以終始，其要無咎之道也。德行者，卦之德行。神者，變而通之。酬酢者，互為賓主。祐神者，先後天也。飲酒之禮，主人獻賓，賓酬主人，主人酬賓。卦反覆相變，而乾、坤、坎、離、大過、頤、小過、中孚不變，此所以能酬酢也。</p><p>子曰：知變化之道者，其知神之所為乎！易有聖人之道四焉：以言者尚其辭，以動者尚其變，以制器者尚其象，以卜筮者尚其佔。是以君子將有為也，將有行也，問焉而以言。其受命也如響，無有遠近幽深，遂知來物。非天下之至精，其孰能與於此。參伍以變，錯綜其數，通其變，遂成天地之文；極其數，遂定天下之象。非天下之至變，其孰能與於此。</p><p>易無思也，無為也，寂然不動，感而遂通天下之故。非天下之至神，其孰能與於此。夫易，聖人之所以極深而研幾也。唯深也，故能通天下之志；唯幾也，故能成天下之務；唯神也，故不疾而速，不行而至。子曰：易有聖人之道四焉者，此之謂也。</p><p>變化之道，盡於叄兩之神。知其道，則知神之所為。辭也，變也，象也，佔也，四者易之變化，本於叄兩者也。叄，天兩地也。錯綜而生變化，其妙至於不可知，然亦不越乎四者。故言者尚其辭，則言必不苟；以動者尚其變，則動必精義；以制器者尚其象，則器必致用；以卜筮者尚其佔，則佔必知來。非神之有為乎？有為，造事也；有行，舉事也。有問者焉，而以易言之，則其辭足以德天下之問。有命者焉，受而應之如響，則其佔足以決天下之疑。問答、佔決，皆辭也。故通言之，無有遠近，以內外言也；無有幽深，以變動言也。心者，天地之鑑，萬物之鏡，顯於叄伍之神，則遠近幽深畢陳乎前。逐。知來物我，與物一也。精之又精，謂之至精。叄位以變者，縱橫十五，天地五十有五之數也。錯之為六七八九，綜之為三百六十。以天地觀之，陰陽三五，一五以變為候者七十二，二五以變為旬者三十六，三五以變為氣者二十四。三百六十五日，週而復始。故乾之策三十有六者，三六而又二也。坤之策二十有四者，二六而又二也。三其二十四與二其三十六，皆七十二，三其七十二為二百一十六，得乾之策。二其七十二為百四十四，得坤之策。三畫之卦，三變而反，六畫之卦，五變而復，通六、七、八、九之變，則剛柔相易，遂成天地之文。極五十有五之數，則剛柔有體，遂定天下之象。非成文不足以成物，非定象不定以制器。變之又變，謂之至變。夫有行始於有為，有為始於有思。有思有為者，人也；無思無為者，天也。誰能有思有為而無於人之累乎？其唯易而巳。易有思也，本於無思；有為也，本於無為。合五十有五之數，歸於太極，寂然無聲，其一不動，萬化冥會乎其中，有物感之，散為六七八九之變，而天下之所以然者，無乎不通。所謂遠近幽深，遂知來物，乃其一也。精者，精此者也；變者，變此者也。神之又神，謂之至神。精故可以窮深，變故可以與幾。夫易，聖人體之以極深研幾者也。天下之志，藏於無形，非推見至隱者，其能盡通乎？易至精者也。天下之務，其來無窮，非曲得所謂者，其能成乎？易至變者也。疾而速，行而至，有思有為者皆然。易至神也。體！易者，至於不疾而速，不行而至者，極深研幾之效也，莫知其然而然也。故曰：易有聖人之道四焉：</p><p>天一地二，天三地四，天五地六，天七地八，天九地十。子曰：夫易何為者也？夫易，開物成務，冒天下之道，如斯而已者也。是故聖人以通天下之志，以定天下之業，以斷天下之疑。是故蓍之德圓而神，卦之德方以知，六爻之義易以貢。聖人以此洗心，退藏於密，吉凶與民同患。神以知來，知以藏往，其孰能與此哉？古之聰明睿知，神武而不殺者夫。是以明於天之道，而察於民之故，是興神物以前民用。聖人以此齋戒，以神明其德夫。是故闔戶謂之坤，闢戶謂之乾，一闔一闢謂之變，往來不窮謂之通，見乃謂之象，形乃謂之器，制而用之謂之法，利用出入，民鹹用之謂之神。是故易有太極，是生兩儀，兩儀生四象，四象生八卦，八卦定吉凶，吉凶生大業。是故法象莫大乎天地，變通莫大乎四時，縣象著明，莫大乎日月，崇高莫大乎富貴。備物致用，立成器以為天下利，莫大乎聖人。探賾索隱，鉤深致遠，以定天下之吉凶，成天下之亹亹者，莫大乎蓍龜。是故天生神物，聖人則之；天地變化，聖人效之；天垂象，見吉凶，聖人象之；河出圖，洛出書，聖人則之。</p><p>易有四象，所以示也；繫辭焉，所以告也；定之以吉凶，所以斷也。易曰：自天祐之，吉無不利。子曰：祐者，助也。天之所助者，順也；人之所助者，信也。履信思乎順，又以尚賢也。是以自天祐之，吉無不利也。</p><p>萬物在天地間，不離乎五十有五之數，聖人雖不言，其能逃乎？然則易之為書，何為者也？物有理，易則開之；事有時，易則成之。聖人冒天下之道，所謂易者，如斯而已者也。冒天下之道者，日月所照，霜露所墜，舟車所至，凡有血氣者，必待此道而後覆冒。關子明曰：象生有定數，吉凶有前期，變而能通，則治亂有可易之理，天命人事，其同歸乎。故聖人以此通天下之志，謂其極深也。以此定天下之業，謂其成務也。以此斷天下之疑，謂其受命如響也。天下之業定，則務既成矣。聖人於天地五十有五之數，蓋有超然獨得而遺乎數者，是故蓍運無窮，可以前知，其德圓而神也。聖人以此洗心，酬酢萬變，一毫不留於胸中。卦成不易，爻見而策藏，其德方以知也。聖人以此退藏，遁於無形，深不可測。六爻之義，唯變是適，上下內外相易，以告吉凶，聖人以此吉凶與民同患。夫洗心退藏，若絕倫離類，則過矣，是以吉凶與民同患。開物於幾先，故曰知來，所謂可以前知也。明憂患而弭其故，故曰藏往，所謂爻見而策藏也。惟吉凶與民同患，是以有開物成務，冒天下之道，此所謂不與聖人同憂者也。若舍是道，唯數而已，則易於天地為贅矣。上言蓍神卦知爻義，而總之以神知者，言卦，則爻在其中，孰能與於此者哉？古者聰明不蔽於耳目，睿知不蔽于思慮，有武而不殺者。夫有武不殺，萬物自服，故謂之神武。物之矇蔽，動違諸理，不得已而用刑，至於殺之，豈得已哉？聖人憂之，是以明於天之道，察於民之故。明於天之道，而不察於民之故，知天而巳，非聖人也，無非物也。天地五十有五之數，見於蓍龜，故謂之神物。是興神物，前百姓之日用，示之以吉凶之理，使知違順取捨其效，至於刑措不用，兵革不試，何殺之有？然非聰明睿知，豈能明察如此？聖人以此齋潔戒慎恐懼於不聞不睹，所謂誠也。神明其德者，配天地也，故其民有肅心而不欺，民至於不欺至矣。坤自夏至以一陰右行，萬物從之而入，故曰闔戶，謂之坤。乾自冬至以一陽左行，萬物從之而出，故曰闢戶，謂之乾。坤闔則陽變而陰，乾闢則陰變而陽，故一闔一闢謂之變。闔者，往也，闢者，來也。一闔一闢，往來相感，其機有不得息者，故往來不窮，謂之通。氣聚而有見，故謂之象。象成而有形，故謂之器。利用此道，以動靜出入，而蚩蚩之民鹹日用之，莫知其然，故謂之神。七者同出而異名，其變化之道，神之所為乎？知闔闢變通者，明於天之道。知利用出入，民鹹用之者，察於民之故。乾天坤地，而曰明於天之道者，乾兼坤也。闔闢，以一歲言之，寒暑也；以一日言之，晝夜也；以一身言之，出入之息，死生之變也。無闔則無闢，無靜則無動，此歸藏所以先坤歟。此以不言，是興神物。極，中也，太極中之至歟！易有太極四十有九，合而為一乎。四象八卦具而未動，謂之太極，在人則喜怒哀樂之未發者也。陰，陽匹也，故謂之儀。太極動而生陽，極動而生陰，陰極復動而生陽。始動靜者，少也，極動靜者，老也，故生四象。乾，老陽也；震、坎、艮，少陽也。坤，老陰也。巽、離、兌，少陰也。故四象生八卦。卦有爻，爻有位，剛柔相文，有當否，故八卦定吉凶。有吉凶則有利害，人謀用矣，故生大業。八卦定吉凶者，開物也。吉凶生大業者，成務也。法象莫大乎天地，故定乾坤也。變通莫大乎四時，故明六爻也。縣象著明莫大乎日月，故用坎離也。積而崇高者，富貴也。富貴然後可與人共位，食祿行道，爻之尊位是也，故莫大乎富貴。備百物，致民用，立成器，如網罟耒耜之類，以為天下利，唯聖人能之，象言先王大人君子之所以者是也，故莫大乎聖人。天地鬼神之奧，幽賾隱伏，深遠而難窮，探取之，搜索之，鉤出之，使自至之，以定吉凶之未形，以成亹亹之不巳，唯蓍龜能之，故莫大乎蓍龜。聖人觀天地四時日月，又考之蓍龜而作易，以通神明之德，以類萬物之情，處崇高之富貴，備物致用，立成器，建卜筮。然則通天下之志，定天下之業，斷天下之疑，非聖人其孰能之？是以成位兩間，與天地並立，故曰大哉人謨。舍此而能覆冒天下者，未之見也。蓍一根而百莖，龜具八卦五行，天地之數，神物也，故聖人則之。天地變化，四時行焉，萬物生焉，故聖人效之。日月五星，天象也，天不言，示之以象，吉凶見矣，故聖人象之。河圖九宮，洛書五行，聖人則之。效之者，效之以六爻之動，故曰爻者，效天下之動者也。象之者，象也。故曰象也者，像也。於蓍、龜、圖、書言則之者，大衍之數，八卦五行作易者則之，故乾、坤、坎、離、震、巽、艮、兌三畫之卦爻，合皆九，六、七、八、九，數皆十五，水六，火七，木八，金九，五行之數具焉。傳曰：聖人以蓍龜而信天地四時、日月之象數，以河圖、洛書而信蓍龜之象數。信矣，其不疑也，於是乎作易。易有四象，聖人所以示吉凶也。繫辭焉而命之，所以告吉凶也。易於吉凶，有以利言者，有以情遷者，有義命當吉、當兇、當否、當亨者，一以貞勝而不顧，非聖人不能定也。定之者，所以斷之。易曰：自天祐之，吉無不利。大有上九，辭也。乾為天，為人。祐，助也。坤為順。三與二，孚，信也。天之所助者，順理也。人之所助者，信相與也。六五履信而思乎順，又自下而上賢，是以自天祐之，吉無不利。言此者，明獲天人之利，然後吉無不利。聖人明於天之道，察於氏之故，合天人者也。</p><p>子曰：書不盡言，言不盡意。然則聖人之意，其不可見乎？子曰：聖人立象以盡意，設卦以盡情偽繫辭焉以盡其言，變而通之以盡利，鼓之舞之以盡神。</p><p>乾坤其易之縕邪？乾坤成列，而易立乎其中矣。乾坤毀，則無以見易，易不可見，則乾坤或幾乎息矣。是故形而上者謂之道，形而下者謂之器，化而裁之謂之變，推而行之謂之通，舉而錯之天下之民謂之事業。是故夫象，</p><p>聖人有以見天下之賾，而擬諸其形容，象其物宜。是故謂之象。</p><p>聖人有以見天下之動，而觀其會通，以行其典禮，繫辭焉以斷其吉凶，是故謂之爻。極天下之賾者存乎卦，鼓天下之動者存乎辭。化而裁之存乎變，推而行之存乎通，神而明之存乎其人，默而成之，不言而信，存乎德行。</p><p>言之難諭者。不能盡形之於書。意之難傳者，不能盡見之於言。然聖人之意，終不可見於天下後世乎。夫有意斯有名。有名斯有象。意至賾也。聖人於無形之中。建立有象。因象而得名。因名而得意。則言之所不能盡見者盡矣。君子小人。情偽而巳矣。情則相應。偽則相違。聖人陳卦以示之，斷之以中正，而君子小人見，然後著情去偽，而其意誠矣。系之卦辭，又系之爻辭，以吉凶明告之，與卦象相發，則書之所不能盡形者盡矣。陰極變陽，陽極變陰，當變而變則通，不變則窮，窮非道也，變而通之，則無所不利，而道行矣。鼓舞者，鼓之於此，舞之於彼，動止應節，莫知其然，神也。橫渠曰：辭不鼓舞，則不足以盡神。爻至於變通以盡利，辭至於鼓舞以盡神，則聖人之意幾無餘蘊矣。乾坤成列，則象爻變動蘊於其中。乾坤，體也。象爻變動，用也。體毀則用不可見，用不可見，則體因是息矣。故曰：</p><p>乾坤其易之蘊邪！乾坤毀，則無以見易，易不可見，則乾坤幾乎息矣。乾，健也；坤，順也。健順者，意也。謂之乾坤者，名也。乾奇坤偶者，象也。象成而著者，形也。形而上者謂之道，變通也；形而下者謂之器，執方也。然則變通者，易之道，執方者易之器。是故語道而至於不可象，則名言亡矣。變通一也，離而言之則二。今天地之化，一息不留，聖人指而裁之，則謂之變。故晝夜六時，寒暑六氣，剛柔六位，因其化而裁之，以著其變之微。故曰化而裁之謂之變。晝夜相推為一日，寒暑相推為一歲，剛柔相推為一卦，推之則通，故曰推而行之謂之通。又曰：剛柔相推，變在其中矣。知此則知變通一也。舉此道而錯之於天下，謂之事業，又曰通變之謂事。知此則知事業通變一也。聖人見天下之至賾，將以示人，故擬諸其形容，象其物之宜。形，一定也，剛柔以立本也。容，變動也，變通以趨時也，是故謂之象。立象，則卦也，變通也，在其中矣。聖人見大下之至動，既觀其會通之時，損益典禮以行之矣。又系之辭以斷其疑，曰：如是而吉，如是而兇，是故謂之爻。繫辭則變通在其中矣。然則體易者，欲極天下之至賾者，存乎卦可也，存乎卦則見象矣。欲鼓天下之至動者，存乎辭可也，存乎辭則見變通矣。化而裁之，其化有漸，存乎爻之變可也；推而行之，其利不窮，存乎爻之通可也。神而藏用，明而顯仁，存乎古之人可也。革存乎湯武，明夷存乎文王，箕子復存乎顏氏之子，故曰存乎其人。默而成之，言不下帶而道存者，以心感心也，存諸巳也。故曰不言而信，存乎德行。易至於存乎德行，則得意志象我，與聖人一也。上系終於默然成之。不言而信，下系終於六辭。語、默一也。周易繫辭上傳第七。</p>',30)])])}const m=a(n,[["render",r]]);export{h as __pageData,m as default};
